{
  "action_type": "WriteFile",
  "target": "password-safety-meter.html",
  "arguments": {
    "content": "<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Password Safety Meter</title>
    <style>
        .meter {
            width: 300px;
            height: 20px;
            background-color: #eee;
        }
        .bar {
            height: 100%;
            background-color: #4caf50;
            width: 0;
        }
    </style>
</head>
<body>
    <h1>Password Safety Meter</h1>
    <input type="password" id="password" placeholder="Enter your password">
    <div class="meter">
        <div class="bar" id="bar"></div>
    </div>
    <script>
        document.getElementById('password').addEventListener('input', function() {
            const password = this.value;
            let strength = 0;
            if (password.length >= 8) strength += 1;
            if (/[a-z]/.test(password)) strength += 1;
            if (/[A-Z]/.test(password)) strength += 1;
            if (/\d/.test(password)) strength += 1;
            if (/[^a-zA-Z0-9]/.test(password)) strength += 1;
            const bar = document.getElementById('bar');
            bar.style.width = (strength * 20) + '%';
        });
    </script>
</body>
</html>"
  },
  "reason": "A simple HTML file to display a password safety meter based on the strength of the entered password."
}
